package factory.fun;
import android.app.Activity;
import android.os.Bundle;
import android.content.SharedPreferences;
import android.content.Context;
import android.graphics.*;
import android.view.*;
import android.widget.*;
import android.text.InputType;
import java.util.*;
public final class MainActivity extends Activity {


 private final int accent=0xff087d9a,ink=0xff172337;
 private android.graphics.drawable.GradientDrawable shape(int color,int radius){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 private LinearLayout.LayoutParams spaced(int height,int top,int bottom){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,height);p.setMargins(0,dp(top),0,dp(bottom));return p;}
 private void hero(View v,int height){v.setBackground(shape(0xffedf2f8,20));v.setClipToOutline(true);root.addView(v,spaced(dp(height),8,12));}
 private void buzz(View v){v.performHapticFeedback(HapticFeedbackConstants.VIRTUAL_KEY);}

 private LinearLayout root;private ScrollView scroll;private TextView status;private SharedPreferences prefs;
 private String t(String en,String ko,String ja){String l=getResources().getConfiguration().getLocales().get(0).getLanguage();return "ko".equals(l)?ko:"ja".equals(l)?ja:en;}
 private int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 private void setup(String intro){prefs=getSharedPreferences("local",MODE_PRIVATE);scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(0xfff6f8fc);root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(dp(22),dp(18),dp(22),dp(30));scroll.addView(root);setContentView(scroll);scroll.setOnApplyWindowInsetsListener((v,i)->{android.graphics.Insets a=i.getInsets(WindowInsets.Type.systemBars()|WindowInsets.Type.displayCutout());v.setPadding(a.left,a.top,a.right,a.bottom);return i;});TextView title=label(getString(R.string.app_name));title.setTextSize(34);title.setTextColor(accent);title.setTypeface(null,Typeface.BOLD);label(intro);status=label(t("Ready","준비 완료","準備完了"));status.setTextColor(accent);status.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);}
 private TextView label(String s){TextView v=new TextView(this);v.setText(s);v.setTextSize(16);v.setTextColor(ink);v.setPadding(0,dp(6),0,dp(6));root.addView(v);return v;}
 private Button button(String s,Runnable action){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setMinHeight(dp(48));b.setTextColor(Color.WHITE);b.setTextSize(16);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));b.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x44ffffff),shape(accent,16),null));b.setOnClickListener(v->{buzz(v);action.run();});root.addView(b,spaced(dp(52),5,5));return b;}
 private EditText edit(String name,String value){label(name);EditText e=new EditText(this);e.setContentDescription(name);e.setText(value);e.setTextColor(ink);e.setPadding(dp(14),dp(12),dp(14),dp(12));e.setBackground(shape(Color.WHITE,14));root.addView(e,spaced(-2,4,8));return e;}
 private Spinner options(String title,String... items){label(title);Spinner s=new Spinner(this);s.setContentDescription(title);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,items));s.setBackgroundTintList(android.content.res.ColorStateList.valueOf(accent));root.addView(s,spaced(dp(48),4,8));return s;}
 private void change(Spinner s,Runnable r){s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){r.run();}public void onNothingSelected(android.widget.AdapterView<?> p){}});}

 private int points,fish;private long last;private TextView count;private Tank tank;private Spinner backgrounds;private final String[] symbols={"🐟","🐠","🐡","🦀","🐙","🪼"};
 private String[] names(){return new String[]{t("Silver fish","은빛 물고기","銀色の魚"),t("Clownfish","흰동가리","クマノミ"),t("Pufferfish","복어","フグ"),t("Crab","게","カニ"),t("Octopus","문어","タコ"),t("Jellyfish","해파리","クラゲ")};}
 @Override public void onCreate(Bundle state){super.onCreate(state);setup(t("A little illustrated aquarium. Feed your pets and unlock species.","작은 수족관을 꾸미고 먹이를 주며 생물을 모아 보세요.","小さな水槽で餌をあげ、生き物を集めよう。"));points=Rules.bound(prefs.getInt("points",0));fish=Math.max(1,Math.min(6,prefs.getInt("fish",1)));last=prefs.getLong("last",0);count=label("");tank=new Tank(this);tank.setContentDescription(t("Animated aquarium","움직이는 수족관","動く水槽"));hero(tank,340);tank.setOnClickListener(v->{if(feed()){buzz(v);tank.invalidate();}});backgrounds=options(t("Tank theme","수조 테마","水槽テーマ"),t("Ocean","바다","海"),t("Lagoon","석호","ラグーン"),t("Night","밤바다","夜の海"));backgrounds.setSelection(Math.max(0,Math.min(2,prefs.getInt("theme",0))));change(backgrounds,()->{save();tank.invalidate();});button(t("Feed fish +1","먹이 주기 +1","餌をあげる +1"),()->feed());button(t("Unlock next species (5 points)","다음 생물 해금 (5점)","次の生き物を解放（5点）"),()->{if(fish>=6){status.setText(t("Collection complete!","모두 모았어요!","コンプリート！"));return;}if(points<5){status.setText(t("Need 5 points","5점이 필요해요","5点が必要"));return;}points-=5;fish++;save();refresh();});refresh();}
 private boolean feed(){long now=System.currentTimeMillis();if(now>=last&&now-last<3000){status.setText(t("Give them a moment","조금 기다려 주세요","少し待ってね"));return false;}last=now;points=Rules.bound(points+1);save();refresh();return true;}
 private void save(){prefs.edit().putInt("points",points).putInt("fish",fish).putLong("last",last).putInt("theme",backgrounds.getSelectedItemPosition()).apply();}
 private void refresh(){StringBuilder s=new StringBuilder(t("Feed points: ","먹이 점수: ","餌ポイント: ")).append(points).append("   ").append(fish).append("/6");for(int i=0;i<fish;i++)s.append("\n").append(symbols[i]).append(" ").append(names()[i]);count.setText(s);tank.invalidate();}

 private void fishArt(Canvas c,Paint p,float x,float y,float r,int type,boolean left){c.save();c.translate(x,y);if(left)c.scale(-1,1);int[] palette={0xffb4d9f6,0xffff9948,0xfff1cf72,0xffec7167,0xffcf9af0,0xff89f0d8};p.setColor(palette[type]);p.setStyle(Paint.Style.FILL);
 if(type==3){for(int a=0;a<4;a++){float k=(a-1.5f)*r*.35f;p.setStrokeWidth(r*.13f);p.setStrokeCap(Paint.Cap.ROUND);c.drawLine(-r*.55f,k,-r*1.05f,k+r*.2f,p);c.drawLine(r*.55f,k,r*1.05f,k+r*.2f,p);}c.drawOval(-r*.7f,-r*.5f,r*.7f,r*.5f,p);c.drawCircle(-r*.75f,-r*.5f,r*.25f,p);c.drawCircle(r*.75f,-r*.5f,r*.25f,p);}
 else if(type==4||type==5){c.drawOval(-r*.7f,-r*.8f,r*.7f,r*.4f,p);p.setStrokeWidth(r*.13f);p.setStrokeCap(Paint.Cap.ROUND);for(int a=0;a<6;a++){float k=(a-2.5f)*r*.21f;Path arm=new Path();arm.moveTo(k,r*.12f);arm.cubicTo(k-r*.3f,r*.5f,k+r*.3f,r*.6f,k,r*1.05f);p.setStyle(Paint.Style.STROKE);c.drawPath(arm,p);}p.setStyle(Paint.Style.FILL);}
 else{Path tail=new Path();tail.moveTo(-r*.62f,0);tail.lineTo(-r*1.25f,-r*.55f);tail.lineTo(-r*1.25f,r*.55f);tail.close();c.drawPath(tail,p);c.drawOval(-r*.85f,-r*.60f,r*.9f,r*.60f,p);p.setColor(0x55ffffff);c.drawOval(-r*.55f,-r*.44f,r*.48f,-r*.05f,p);if(type==1){p.setColor(Color.WHITE);c.drawRoundRect(-r*.28f,-r*.54f,-r*.05f,r*.54f,r*.07f,r*.07f,p);c.drawRoundRect(r*.28f,-r*.45f,r*.49f,r*.45f,r*.07f,r*.07f,p);}}
 p.setColor(Color.WHITE);c.drawCircle(r*.42f,-r*.18f,r*.14f,p);p.setColor(0xff172337);c.drawCircle(r*.46f,-r*.18f,r*.075f,p);c.restore();}

 private class Tank extends View{Paint p=new Paint(Paint.ANTI_ALIAS_FLAG);Tank(Context c){super(c);}protected void onDraw(Canvas c){float w=getWidth(),h=getHeight();int theme=backgrounds==null?0:Math.max(0,backgrounds.getSelectedItemPosition());int[][] palettes={{0xff46c3df,0xff063a69},{0xff82dfc1,0xff12665d},{0xff293b76,0xff090e2d}};p.setShader(new LinearGradient(0,0,0,h,palettes[theme],null,Shader.TileMode.CLAMP));c.drawRect(0,0,w,h,p);p.setShader(null);long time=android.os.SystemClock.uptimeMillis();p.setColor(0xffd3b07a);c.drawOval(-w*.1f,h*.87f,w*1.1f,h*1.15f,p);for(int k=0;k<8;k++){float x=w*(k+.5f)/8;Path weed=new Path();weed.moveTo(x,h*.94f);weed.quadTo(x+dp(18),h*.79f,x+dp(5),h*(.65f+(k%3)*.08f));weed.quadTo(x+dp(2),h*.83f,x-dp(8),h*.94f);weed.close();p.setColor(k%2==0?0xff27795e:0xff44986c);c.drawPath(weed,p);}p.setStyle(Paint.Style.STROKE);p.setStrokeWidth(dp(1.5f));p.setColor(0x80ffffff);for(int k=0;k<9;k++){float x=w*(k+.5f)/9,y=h-((time/18f+k*h/9)%h);c.drawCircle(x,y,dp(3+k%4),p);}p.setStyle(Paint.Style.FILL);for(int f=0;f<fish;f++){double phase=time/1700d+f*1.7;float r=dp(25+f%3*4),x=r*1.5f+(float)((Math.sin(phase)+1)*.5*Math.max(0,w-r*3));float y=h*(.23f+(f%3)*.21f)+(float)Math.sin(phase*2)*dp(9);fishArt(c,p,x,y,r,f,Math.cos(phase)<0);}if(isShown())postInvalidateDelayed(35);}}
 }